// 'CQRS' order command handler
async function submitOrderHandler(cmd: SubmitOrderCommand): Promise<OrderDTO> {
  // Load aggregate
  const order = await orderRepo.findById(cmd.orderId);
  const customer = await customerRepo.findById(order.customerId);

  // Validate invariant
  if (order.total > customer.creditLimit) {
    throw new Error('Credit limit exceeded');
  }

  // Apply command
  order.status = 'SUBMITTED';
  await orderRepo.save(order);

  // Update read model inline
  await db.query(
    'UPDATE order_dashboard SET status=$1, submitted_at=$2 WHERE order_id=$3',
    ['SUBMITTED', new Date(), cmd.orderId]
  );

  // Return full view DTO for UI refresh
  return buildOrderDTO(order, customer);
}
